// Helper: append events via the watchover tool and return ids.
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';

export const TOOL = '<WORKSPACE>/<PRODUCT_KIT>/tools/watchover.mjs';
export const WS = '<WORKSPACE>/app/watchover';
export const SESSION = '<NATIVE_ID_1514>';
export const AI = { role: 'ai', name: 'ai-deployer' };
export const SP = 'C:<CLIENT_HOME>/AppData/Local/Temp/claude/C--Workspaces-site-03-app/<NATIVE_ID_1514>/scratchpad';

export function append(ev) {
  const full = { actor: AI, session_id: SESSION, ...ev };
  try {
    const out = execFileSync('node', [TOOL, 'append', WS], { input: JSON.stringify(full), encoding: 'utf8' });
    return out.trim().split(/\s+/).find((t) => /^evt-\d+$/.test(t)) ?? out.trim();
  } catch (e) {
    if (e.status === 2) return (e.stdout || '').trim().split(/\s+/).find((t) => /^evt-\d+$/.test(t));
    throw new Error(`append refused: ${e.stdout}\n${e.stderr}`);
  }
}

export function verify(key, status, evidence, summary) {
  const at = new Date().toISOString();
  const id = append({ at, type: 'fact_verified', summary, fact: { key, status }, evidence });
  return { at, id };
}

export function loadState() {
  return JSON.parse(readFileSync(`${WS}/state.json`, 'utf8'));
}

export function commitState(state) {
  state.identity.updated_at = new Date().toISOString();
  state.identity.updated_by = AI;
  const f = `${SP}/candidate.json`;
  writeFileSync(f, JSON.stringify(state, null, 2));
  try {
    return execFileSync('node', [TOOL, 'commit-state', WS, '--file', f], { encoding: 'utf8' });
  } catch (e) {
    throw new Error(`commit-state failed: ${e.stdout}\n${e.stderr}`);
  }
}

import { append, verify, loadState, commitState, AI } from './wo.mjs';

const E = {
  id: 'evidence/0002-gcp-identity.txt',
  inv: 'evidence/0003-gcp-inventory.txt',
  dns: 'evidence/0004-dns-precheck.txt',
  src: 'evidence/0005-source-checkout.txt',
  app: 'evidence/0006-app-config-findings.txt',
  price: 'evidence/0007-price-catalog.txt',
};

const facts = [];
function vf(key, label, value, status, cls, fresh, scope, ev, extra = {}, summary) {
  const { at } = verify(key, status, [ev], summary ?? `Verified ${label}`);
  facts.push({
    key, label, value, status,
    source: status === 'VERIFIED_REMOTE' ? 'remote_observation' : 'local_check',
    class: cls, scope, checked_at: at, fresh_for_minutes: fresh, evidence: [ev], ...extra,
  });
}
function other(key, label, value, status, source, cls, scope, extra = {}) {
  facts.push({ key, label, value, status, source, class: cls, scope, checked_at: null, fresh_for_minutes: null, evidence: [], ...extra });
}

const R = 'VERIFIED_REMOTE', L = 'VERIFIED_LOCAL';
vf('gcp.account', 'Active gcloud account', '<ACCOUNT_EMAIL_011>', R, 'identity', 1440, 'gcloud configuration "sandbox" on this machine', E.id);
vf('gcp.project', 'Target project is active', '<CLOUD_PROJECT> (ACTIVE, no parent org)', R, 'identity', 1440, 'GCP project <CLOUD_PROJECT>', E.id);
vf('gcp.billing_enabled', 'Billing enabled on project', true, R, 'permission', 240, 'GCP project <CLOUD_PROJECT>', E.id);
vf('gcp.permission_owner', 'Account role on project', 'roles/owner', R, 'permission', 240, '<ACCOUNT_EMAIL_011> on <CLOUD_PROJECT>', E.id);
vf('gcp.compute_api_enabled', 'Compute Engine API enabled', true, R, 'resource', 240, 'GCP project <CLOUD_PROJECT>', E.id);
vf('gcp.no_existing_app_resources', 'No VMs, disks, IPs, Cloud Run, buckets', 'none found', R, 'resource', 240,
  'compute instances/disks/addresses, run services, buckets, artifact repos in <CLOUD_PROJECT>', E.inv,
  { negative_result: true, control: 'Same account/project returned non-empty firewall-rules and networks lists in the same run' });
vf('gcp.no_web_firewall_rule', 'No firewall rule opens tcp 80/443', 'none found', R, 'network', 240,
  'firewall rules on network default', E.inv,
  { negative_result: true, control: 'The same listing returned 4 default rules (icmp, internal, rdp, ssh)' });
vf('gcp.quota_ok', 'Regional quotas sufficient', 'australia-southeast1 and us-central1: E2_CPUS 24, IN_USE_ADDRESSES 8, SSD_TOTAL_GB 250, all unused', R, 'resource', 240,
  'compute quotas in australia-southeast1 and us-central1', E.inv);
vf('dns.<W3_RUN_HOST_LABEL>_record_absent', 'No DNS record for <W3_RUN_HOST_LABEL>.<EXPERIMENT_DOMAIN> yet', 'NXDOMAIN', R, 'network', 240,
  'public DNS via 1.1.1.1 for <W3_RUN_HOST_LABEL>.<EXPERIMENT_DOMAIN>', E.dns,
