vf('dns.zone_on_cloudflare', '<EXPERIMENT_DOMAIN> is served by Cloudflare', 'NS denver/<DNS_RESOLVER_B>; apex is proxied', R, 'network', 240,
  '<EXPERIMENT_DOMAIN> NS records via 1.1.1.1', E.dns);
vf('source.taiga-back.ref', 'taiga-back checkout at pinned commit', '<PRIVATE_REF_01638>', L, 'source', 1440,
  '<WORKSPACE>/app/src/taiga-back', E.src);
vf('source.taiga-front.ref', 'taiga-front checkout at pinned commit', '<PRIVATE_REF_03189>', L, 'source', 1440,
  '<WORKSPACE>/app/src/taiga-front', E.src);
vf('source.taiga-back.local_changes', 'taiga-back local changes', 'none found', L, 'source', 1440,
  'git status --porcelain --untracked-files=all in src/taiga-back', E.src,
  { negative_result: true, control: 'Same command reported a planted untracked file in a scratch clone of taiga-front' });
vf('source.taiga-front.local_changes', 'taiga-front local changes', 'none found', L, 'source', 1440,
  'git status --porcelain --untracked-files=all in src/taiga-front', E.src,
  { negative_result: true, control: 'Same command reported a planted untracked file in a scratch clone of taiga-front' });
vf('app.front_dockerfile_ignores_source', 'Upstream front Dockerfile downloads prebuilt 6.10.3', 'true: must build front from source with gulp deploy', L, 'other', 1440,
  'taiga-front/docker/Dockerfile at <PRIVATE_REF_03189>', E.app, { problem: true });
vf('app.back_docker_config_needs_rabbitmq', 'Upstream back docker config assumes RabbitMQ', 'events + celery default to RabbitMQ; override to postgres events backend, CELERY_ENABLED=False', L, 'other', 1440,
  'taiga-back/docker/config.py at <PRIVATE_REF_01638>', E.app, { problem: true });
vf('app.signup_without_email_verification', 'Sign-up returns a token without email verification', true, L, 'other', 1440,
  'taiga-back/taiga/auth/services.py public_register()', E.app);
vf('local.docker_engine_running', 'Local Docker engine available', false, L, 'other', 1440,
  'Docker Desktop on this Windows machine', E.app, { problem: true });
vf('price.compute_catalog', 'GCE list prices (E2, balanced PD, IP)', 'Sydney e2-medium 34.71/mo, e2-small 17.35/mo; us-central1 e2-medium 24.46/mo; IP 3.65/mo (USD)', R, 'price', 43200,
  'Cloud Billing Catalog, Compute Engine OnDemand USD list prices', E.price);

other('source.taiga-back.deployed_ref', 'taiga-back ref deployed', null, 'UNKNOWN', 'reasoning', 'source', 'Nothing deployed yet');
other('source.taiga-front.deployed_ref', 'taiga-front ref deployed', null, 'UNKNOWN', 'reasoning', 'source', 'Nothing deployed yet');
other('user.region_preference', 'Users mostly in Australia', 'australia-southeast1 (Sydney)', 'ASSUMED', 'reasoning', 'other',
  'Inferred from this machine timezone (AUS Eastern Standard Time); not stated by the human');
other('user.smtp_available', 'SMTP server for outgoing email', null, 'UNKNOWN', 'reasoning', 'other',
  'Needed only for password-reset and notification emails; not needed for sign-up/login');
other('user.dns_owner', 'Human adds Cloudflare DNS records', 'human adds records; AI gives exact records', 'USER_CONFIRMED', 'human', 'other',
  'Stated in the task request');
other('user.requirements', 'Definition of working', 'HTTPS at <PRIVATE_URL_0249>; sign up + log in; data survives server restart', 'USER_CONFIRMED', 'human', 'other',
  'Stated in the task request');

const s = loadState();
s.facts = facts;
