import { loadState, commitState } from './wo.mjs';

const s = loadState();
const priceAt = s.facts.find((f) => f.key === 'price.compute_catalog').checked_at;

s.brief.topology = 'One Compute Engine VM (Debian 12 + Docker Compose) with a reserved static external IP. Three containers: caddy (the only public part, tcp 80/443), taiga-back (internal :8000) and postgres (internal only). The frontend is built from the pinned commit and served by caddy. Postgres data, uploaded media and caddy certificates live on a separate 10 GiB persistent data disk (auto-delete off) mounted at /srv/taiga, with a daily snapshot schedule keeping 7 days. A firewall rule opens tcp 80/443 only to this VM. Cloudflare A record <W3_RUN_HOST_LABEL> -> the static IP, DNS only.';
s.brief.resource_rationale = 'A single small VM fits a small team and is the cheapest shape that keeps all of Taiga in one place. Restarts are safe because the database and uploads sit on a persistent disk that is separate from the VM and is also snapshotted daily. Caddy gets a free Let\'s Encrypt certificate itself, so no load balancer or certificate service is needed. Everything can be rebuilt from the pinned commits.';
s.brief.heavier_alternatives = [
  { alternative: 'Cloud SQL for PostgreSQL', why_unnecessary: 'Adds at least ~10-30 USD/month and private networking; a Postgres container on a snapshotted persistent disk is enough for a small team.' },
  { alternative: 'HTTPS load balancer + Google-managed certificate', why_unnecessary: 'About 18 USD/month minimum; caddy on the VM gets and renews the certificate for one hostname.' },
  { alternative: 'Cloud Run for frontend and API', why_unnecessary: 'Would need Cloud SQL and object storage for uploads (taiga-back stores media on local disk), plus a load balancer or domain mapping for the custom domain.' },
  { alternative: 'GKE (Kubernetes)', why_unnecessary: 'Cluster fee and operational overhead are not justified for three containers on one host.' },
  { alternative: 'RabbitMQ + taiga-events/taiga-async', why_unnecessary: 'Not part of the two given repos; Taiga runs tasks inline and works without live updates (pages refresh instead).' },
];
const common = 'Debian 12 VM with Docker; 20 GiB balanced boot disk; 10 GiB balanced data disk (auto-delete off) with daily snapshots kept 7 days; reserved static external IP; firewall tcp 80/443; caddy + taiga-back + postgres containers';
s.plan.tiers = [
  { id: 'syd-medium', name: 'Sydney, e2-medium (2 shared vCPU, 4 GiB)', composition: `e2-medium in australia-southeast1-b; ${common}`,
    region: 'australia-southeast1 (Sydney)', cost_range: { low: 42, high: 48, currency: 'USD', period: 'month' }, price_checked_at: priceAt,
    load_assumption: 'Up to ~30 active users; the frontend build on the VM (~1.5-2 GiB RAM peak) fits comfortably',
    uncertainty: 'List prices before tax, no discounts; snapshot storage and egress are estimates (~0-3 USD); the 744 free in-use IP hours may not apply, so the IP is priced at full rate' },
  { id: 'syd-small', name: 'Sydney, e2-small (2 shared vCPU, 2 GiB)', composition: `e2-small in australia-southeast1-b plus 2 GiB swap; ${common}`,
    region: 'australia-southeast1 (Sydney)', cost_range: { low: 25, high: 30, currency: 'USD', period: 'month' }, price_checked_at: priceAt,
    load_assumption: 'Up to ~10 active users; tighter memory, slower first build (uses swap)',
    uncertainty: 'Same price caveats as syd-medium; risk that the frontend build is slow or needs a retry under 2 GiB RAM' },
  { id: 'usc-medium', name: 'Iowa (us-central1), e2-medium', composition: `e2-medium in us-central1-a; ${common}`,
    region: 'us-central1 (Iowa, USA)', cost_range: { low: 31, high: 36, currency: 'USD', period: 'month' }, price_checked_at: priceAt,
    load_assumption: 'Same as syd-medium; roughly 150-200 ms extra latency for users in Australia',
    uncertainty: 'Same price caveats as syd-medium' },
];
s.plan.default_tier = 'syd-medium';
s.activity = { ...s.activity, summary: 'Plan written; starting the read-only view for the human', waiting_on: 'ai',
  last_progress: { at: new Date().toISOString(), summary: 'Plan with three priced tiers recorded' } };
