// Usage: node step.mjs <spec.json>
// spec: { summary, target, display, argv:[...], evidence:"0010-x.txt", kinds:[...], related:[...], resultSummary, stateChange }
// Appends intent, runs argv (gcloud via cmd shim), saves output as evidence, appends result.
import { spawnSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { append, WS } from './wo.mjs';
import { redact } from './redact.mjs';

const spec = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const intent = append({ type: 'intent', summary: spec.summary, target: spec.target, action: spec.display,
  action_kinds: spec.kinds, ...(spec.related ? { related: spec.related } : {}) });
const started = new Date().toISOString();
const r = spawnSync(spec.argv[0], spec.argv.slice(1), { encoding: 'utf8', shell: true, maxBuffer: 64 * 1024 * 1024, timeout: spec.timeoutMs ?? 900000 });
const ended = new Date().toISOString();
const out = redact(`$ ${spec.display}\n# started ${started}  ended ${ended}  exit ${r.status}\n--- stdout\n${r.stdout ?? ''}\n--- stderr\n${r.stderr ?? ''}\n`);
writeFileSync(`${WS}/evidence/${spec.evidence}`, out);
const ok = r.status === 0;
const res = append({ type: 'result', summary: ok ? spec.resultSummary : `FAILED: ${spec.summary} (exit ${r.status})`, outcome: ok ? 'succeeded' : 'failed',
  ...(ok && spec.stateChange ? { state_change: spec.stateChange } : {}), evidence: [`evidence/${spec.evidence}`], related: [intent] });
console.log(JSON.stringify({ intent, result: res, exit: r.status, ended }));
console.log(out.length > 6000 ? out.slice(0, 2500) + '\n...\n' + out.slice(-3000) : out);
process.exit(ok ? 0 : 1);

// Best-effort redaction of secret-looking values before output is saved as evidence.
export function redact(text) {
  return text
    .replace(/((?:PASSWORD|SECRET|SECRET_KEY|TOKEN|PASS)[A-Z_]*\s*[=:]\s*)\S+/gi, '$1[REDACTED]')
    .replace(/(ya29\.)[A-Za-z0-9._-]+/g, '$1[REDACTED]')
    .replace(/(postgres(?:ql)?:\/\/[^:\s]+:)[^@\s]+@/gi, '$1[REDACTED]@')
    .replace(/(amqp:\/\/[^:\s]+:)[^@\s]+@/gi, '$1[REDACTED]@')
    .replace(/(-----BEGIN [A-Z ]*PRIVATE KEY-----)[\s\S]*?(-----END [A-Z ]*PRIVATE KEY-----)/g, '$1[REDACTED]$2');
}

// Usage: node update.mjs <spec.json>
// spec: { verify:[{key,label,value,status,class,fresh,scope,evidence:[..],extra:{}}], facts:[full fact objects to upsert (non-verified)],
//         stale:[keys], resources:[resource objects to upsert], secrets:[upsert], activity:{...partial}, progress:"text", next:{...},
//         addOpen:[...], removeOpenMatching:"substring", stage:"x", stageSummary:"..." }
import { readFileSync } from 'node:fs';
import { append, verify, loadState, commitState } from './wo.mjs';

const spec = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const pending = [];
for (const v of spec.verify ?? []) {
  const { at } = verify(v.key, v.status, v.evidence, v.summary ?? `Verified ${v.label}`);
  pending.push({ key: v.key, label: v.label, value: v.value, status: v.status,
    source: v.status === 'VERIFIED_REMOTE' ? 'remote_observation' : 'local_check', class: v.class, scope: v.scope,
    checked_at: at, fresh_for_minutes: v.fresh, evidence: v.evidence, ...(v.extra ?? {}) });
}
if (spec.stage) append({ type: 'stage_change', summary: spec.stageSummary, stage: { from: loadState().stage, to: spec.stage } });

const s = loadState();
if (spec.stage) s.stage = spec.stage;
const upsert = (arr, item, k) => { const i = arr.findIndex((x) => x[k] === item[k]); if (i >= 0) arr[i] = item; else arr.push(item); };
for (const f of [...pending, ...(spec.facts ?? [])]) upsert(s.facts, f, 'key');
for (const k of spec.stale ?? []) { const f = s.facts.find((x) => x.key === k); if (f) f.status = 'STALE'; }
for (const r of spec.resources ?? []) upsert(s.resources, r, 'id');
for (const r of spec.secrets ?? []) upsert(s.secrets, r, 'name');
if (spec.removeOpenMatching) s.open_items = s.open_items.filter((o) => !o.text.includes(spec.removeOpenMatching));
for (const o of spec.addOpen ?? []) s.open_items.push(o);
const now = new Date().toISOString();
if (spec.activity) s.activity = { ...s.activity, ...spec.activity };
if (spec.progress) s.activity.last_progress = { at: now, summary: spec.progress };
if (spec.next) s.next = spec.next;
if (spec.handoff) s.handoff = { ...s.handoff, ...spec.handoff };
if (spec.pending_decision !== undefined) s.pending_decision = spec.pending_decision;
console.log(commitState(s));

